@spec arrange_page_spec  src=tests/specs/arrange_page_spec.lua  loc=1187  cases=50
@exercises commandManager (h.cmgr), configManager (h.cm), arrangeManager (am)
@surface   cmgr:registerAll, cm:set, cmgr:push, am:tracksTakes, cmgr:invoke, cmgr:installManifest, cmgr:scope, cm:get, am:resizeTake, am:trimHead, am:trackSlots
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.SetMediaItemSelected, reaper:setCursor

# Intent
  Pin-tests for arrangePage's Page interface and arrange-scope edit commands.
  Cursor mechanics, off-screen no-op, and selection-precedence: arrange_view_spec.

# Helpers
  @fn newArrangePage(cm, ds, cmgr, chrome, gui)  @ 46-54
  @fn twoSelected(h)  @ 58-77
      -- Two instances of slot 0, one row each at QN 0 and 1, with rows 0..1 banded.
      -- The siblings at QN 10 and 20 are what slots 0 and 1 clone from.

# Cases
  @case 'bind / unbind are no-ops — arrange page never re-keys cm'  [harness]  @ 81-91
  @case 'the arrange facade enumerates the takes over a span of columns and QN'  [harness]  @ 97-126
  @case 'the arrange facade answers the placement a QN falls in on a track'  [harness]  @ 130-146
  @case 'focusState before any render returns both bits false'  [harness]  @ 150-157
  @case 'arrange-scope is registered at module load (cursorRight invokable)'  [harness]  @ 161-168
  @case 'the manifest declares every command the arrange page registers'  [harness]  @ 175-192
  @case 'arrange-scope place commands are registered (drop0/dropA/dropZ invokable)'  [harness]  @ 196-207
  @case 'a place-command drop advances the cursor by cm.arrangeAdvanceBy rows'  [harness]  @ 211-234
  @case 'arrangeAdvanceBy0..9 set cm.arrangeAdvanceBy at project tier'  [harness]  @ 238-249
  @case 'chained Super-D walks down — each clone becomes the selection for the next'  [harness]  @ 253-272
  @case 'a place-command drop inherits the length of an existing instance'  [harness]  @ 276-298
  @case 'arrangeNudgeForward moves the cursor take by one row'  [harness]  @ 302-316
  @case 'arrangeNudgeForward moves a take taller than one row'  [harness]  @ 320-335
  @case 'arrangeEdgeDown lengthens the cursor take by one row'  [harness]  @ 339-357
  @case 'growing a trimmed take moves its end, leaving the head where it was'  [harness]  @ 361-383
  @case 'arrangeEdgeDown silently no-ops at the take-source length cap'  [harness]  @ 387-402
  @case 'arrangeEdgeUp reduces the cursor take by one row'  [harness]  @ 406-422
  @case 'arrangeDeleteTake removes the cursor take'  [harness]  @ 426-440
  @case 'deleteSlot forever-deletes the cursor take\'s slot behind a confirm'  [harness]  @ 446-470
  @case 'deleteSlot no-ops with the cursor off every take'  [harness]  @ 474-490
  @case 'arrangeNudgeForward is a no-op when the next row is occupied'  [harness]  @ 494-510
  @case 'arrangeNudgeBack is a no-op when the take is already at row 0'  [harness]  @ 514-528
  @case 'arrangeEdgeDown against a flush neighbour stores intent; rendered is gap-capped'  [harness]  @ 532-551
  @case 'arrangeNudgeForward steps past a neighbour without a start-collision'  [harness]  @ 555-575
  @case 'arrangeNudgeForward truncates the displaced take when stepping past'  [harness]  @ 579-601
  @case 'arrangeDive switches to the tracker for the cursor MIDI take'  [harness]  @ 605-620
  @case 'createSlot dives the tracker onto the freshly-minted take'  [harness]  @ 624-639
  @case 'arrangeDive over an audio take still switches and restores (no take pinned)'  [harness]  @ 643-657
  @case 'arrangeDive over empty space switches and restores'  [harness]  @ 661-673
  @case 'the dive carries the caret QN, and carries none over empty space'  [harness]  @ 679-698
  @case 'kb edit acts on the cursor take when nothing is selected'  [harness]  @ 702-720
  @case 'kb delete no-ops when the cursor sits off every take'  [harness]  @ 724-742
  @case 'kb nudge no-ops when cursor sits on empty space'  [harness]  @ 746-763
  @case 'an edit command is a no-op when the cursor is over empty space'  [harness]  @ 767-782
  @case 'a second delete finds an empty cell under the cursor — no-op'  [harness]  @ 786-804
  @case 'seedCursorFromReaper lands the cursor on the selected take'  [harness]  @ 808-825
  @case 'seedCursorFromReaper falls back to the edit-cursor row'  [harness]  @ 829-843
  @case 'arrangeTakeProperties routes the focused MIDI take through the tracker facade'  [harness]  @ 852-865
  @case 'arrangeTakeProperties is a no-op on an audio take'  [harness]  @ 869-882
  @case 'arrangeDuplicateBelow drops a pooled clone at the focused take\'s append point'  [harness]  @ 886-902
  @case 'arrangeDuplicateBelow is silent for want of room and on audio takes'  [harness]  @ 906-924
  @case 'arrangeNextVariant past the last of the family swaps the target for a fresh variant'  [harness]  @ 928-959
  @case 'arrangeDuplicateBelow then arrangeNextVariant forks the copy onto a fresh slot'  [harness]  @ 965-989
  @case 'replace mode: a drop swaps the take under the cursor, keeping its start'  [harness]  @ 995-1022
  @case 'a replace with a selection held replaces every selected take'  [harness]  @ 1026-1043
  @case 'the replacements become the selection'  [harness]  @ 1047-1059
  @case 'a shorter replacement pulls the cursor back inside it'  [harness]  @ 1063-1091
  @case 'replace mode disarms on the drop it reinterprets — the next drop places'  [harness]  @ 1095-1123
  @case 'a cursor move disarms replace mode'  [harness]  @ 1127-1153
  @case 'a second arrangeReplaceMode disarms — the mode is a toggle'  [harness]  @ 1157-1184

